            (row.get("deactivated_at") or "", did, row)
            for did, row in notices.items()
            if did not in known_dids
        ]
        missing.sort(key=lambda item: (item[0], item[1]))
        for _, did, row in missing:
            events.append(
                {
                    "cursor": (
                        self._next_did_deactivation_cursor_locked(
                            tenant_id
                        )
                    ),
                    "did": did,
